//! 🔏️ Authored checkpoint identities match the independent BLAKE3 commitment without gathering wide original text.
use super::*;
#[test]
fn original_pending_checkpoint_hashes_authored_unicode_and_authors_in_bounded_turns(){
 let f:serde_json::Value=serde_json::from_str(include_str!("commit-facts.json")).unwrap();let message=f["message"].as_str().unwrap().to_owned()+&f["identity"]["messageSuffixPattern"].as_str().unwrap().repeat(f["identity"]["repeat"].as_u64().unwrap()as usize);let authors:Vec<Author>=f["authors"].as_array().unwrap().iter().map(|row|Author{id:row["id"].as_str().unwrap().into(),name:row["name"].as_str().unwrap().into(),avatar:row["avatar"].as_str().map(str::to_owned)}).collect();let pending:Vec<String>=serde_json::from_value(f["pending"].clone()).unwrap();let prior:Vec<String>=serde_json::from_value(f["parent"]["changeIds"].clone()).unwrap();let mut changes=ArtifactHistoryLedger::new();for row in f["committed"].as_array().unwrap(){changes.try_push(serde_json::from_value::<Change>(row.clone()).unwrap()).unwrap();}
 let input=OriginalPendingCheckpointInput{generation:71,parent:Some(f["parent"]["id"].as_str().unwrap()),prior_change_ids:&prior,changes:&changes,pending_id:f["changeId"].as_str().unwrap(),pending_edits:&pending,pending_description:Some(f["message"].as_str().unwrap()),saved_at:f["savedAt"].as_str().unwrap(),timestamp:f["timestamp"].as_str().unwrap(),message:Some(&message),authors:&authors};let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};
 for cut in [Some(0),Some(1),Some(8),Some(32),Some(128),Some(512),None]{let mut owner=OriginalPendingCheckpointIdentity::default();for turn in 0..100000{if cut==Some(turn)||owner.digest().is_some(){break}let d=owner.demands();assert!(d.copy_bytes<=4096);for axis in [0,1,4]{let mut denied=grant;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,_=>denied.maximum_depth=d.depth-1};let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&input,denied).unwrap());assert_eq!(p,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&input,grant).unwrap());assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(turn<99999);}
  if cut.is_none(){let digest=owner.digest().unwrap();let actual=digest.iter().map(|value|format!("{value:02x}")).collect::<String>();assert_eq!(actual,f["identity"]["digestHex"]);let ids=prior.iter().cloned().chain([f["changeId"].as_str().unwrap().to_owned()]).collect::<Vec<_>>();let reference=content_addressed_checkpoint_id_with_pending_change(input.parent,&ids,&changes,input.pending_id,&pending,input.pending_description,input.saved_at,input.message,&authors,input.timestamp,&[]);assert_eq!(reference,format!("ck-{}",&actual[..16]));}
  let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(grant));assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(owner.terminal_is_empty());
 }
 while changes.pop().is_some(){}
}
